import json, subprocess, sqlite3

# ---- 1. Load WooCommerce products ----
woo = {}
for i in range(1, 30):
    f = f'/tmp/woo_cur_{i}.json'
    try:
        with open(f) as fh:
            d = json.load(fh)
        woo[d['sku']] = {'woo_id': d['id'], 'stock': d['stock_quantity'], 'name': d['name'], 'price': d['price']}
    except:
        pass
print(f'WooCommerce products: {len(woo)}')
for sku in sorted(woo):
    print(f'  {sku}: woo_id={woo[sku]["woo_id"]}, stock={woo[sku]["stock"]}')

# ---- 2. Aggregate warehouse inventory ----
import sqlite3
all_pid_info = {}
total_qty = {}

for city, db_name in [
    ('new_york', 'warehouse_new_york.db'),
    ('boston', 'warehouse_boston.db'),
    ('dallas', 'warehouse_dallas.db'),
    ('los_angeles', 'warehouse_los_angeles.db'),
    ('san_francisco', 'warehouse_san_francisco.db'),
    ('houston', 'warehouse_houston.db'),
]:
    db = f'/app/warehouse/{db_name}'
    conn = sqlite3.connect(db)
    cur = conn.cursor()
    cur.execute('SELECT product_id, quantity FROM inventory')
    for pid, qty in cur.fetchall():
        total_qty[pid] = total_qty.get(pid, 0) + qty
    cur.execute('SELECT product_id, product_name, price FROM products')
    for pid, pname, pprice in cur.fetchall():
        if pid not in all_pid_info:
            all_pid_info[pid] = {'name': pname, 'price': pprice}
    conn.close()

print(f'\nAggregated {len(total_qty)} products')

# ---- 3. Update existing WooCommerce products ----
for pid in sorted(total_qty.keys(), key=lambda x: x.lower()):
    if pid in woo:
        qty = total_qty[pid]
        payload = json.dumps({
            'productId': woo[pid]['woo_id'],
            'productData': {
                'stock_quantity': qty,
                'stock_status': 'instock' if qty > 0 else 'outofstock',
                'manage_stock': True
            }
        })
        result = subprocess.run(
            ['mcp-tool', 'call', 'woocommerce', 'woo_products_update', payload],
            capture_output=True, text=True
        )
        if 'error' not in result.stdout.lower():
            print(f'  UPDATED {pid} -> woo_id={woo[pid]["woo_id"]}, stock={qty}')
        else:
            print(f'  ERROR updating {pid}: {result.stdout[:200]}')

# ---- 4. Create new products ----
for pid in sorted(total_qty.keys(), key=lambda x: x.lower()):
    if pid not in woo:
        info = all_pid_info.get(pid, {'name': pid, 'price': '0'})
        qty = total_qty[pid]
        payload = json.dumps({
            'productData': {
                'sku': pid,
                'name': f'Product {info["name"]}',
                'type': 'simple',
                'regular_price': str(info['price']),
                'stock_quantity': qty,
                'stock_status': 'instock' if qty > 0 else 'outofstock',
                'manage_stock': True
            }
        })
        result = subprocess.run(
            ['mcp-tool', 'call', 'woocommerce', 'woo_products_create', payload],
            capture_output=True, text=True
        )
        if 'error' not in result.stdout.lower():
            print(f'  CREATED {pid}: stock={qty}')
        else:
            print(f'  ERROR creating {pid}: {result.stdout[:200]}')

# ---- 5. Mark sync_status as synced in DBs ----
for city, db_name in [
    ('new_york', 'warehouse_new_york.db'),
    ('boston', 'warehouse_boston.db'),
    ('dallas', 'warehouse_dallas.db'),
    ('los_angeles', 'warehouse_los_angeles.db'),
    ('san_francisco', 'warehouse_san_francisco.db'),
    ('houston', 'warehouse_houston.db'),
]:
    db = f'/app/warehouse/{db_name}'
    conn = sqlite3.connect(db)
    cur = conn.cursor()
    cur.execute("UPDATE inventory SET sync_status='synced', sync_timestamp=datetime('now') WHERE sync_status='pending'")
    conn.commit()
    print(f'  {city}: {cur.rowcount} records synced')
    conn.close()

print('\nDone!')
